import json

class Solution:
    def minNumberOfSemesters(self, n, dependencies, k):
        req = [0] * n
        for u, v in dependencies:
            req[v - 1] |= 1 << (u - 1)

        size = 1 << n
        INF = n + 1
        dp = [INF] * size
        dp[0] = 0

        for mask in range(size):
            if dp[mask] == INF:
                continue

            available = 0
            for i in range(n):
                if (mask & (1 << i)) == 0 and (req[i] & mask) == req[i]:
                    available |= 1 << i

            if available.bit_count() <= k:
                dp[mask | available] = min(dp[mask | available], dp[mask] + 1)
            else:
                sub = available
                while sub:
                    if sub.bit_count() <= k:
                        nxt = mask | sub
                        dp[nxt] = min(dp[nxt], dp[mask] + 1)
                    sub = (sub - 1) & available

        return dp[-1]

