import java.io.*;
import java.util.*;

class Solution {
    public int minNumberOfSemesters(int n, int[][] dependencies, int k) {
        int[] req = new int[n];
        for (int[] e : dependencies) req[e[1] - 1] |= 1 << (e[0] - 1);

        int size = 1 << n, INF = n + 1;
        int[] dp = new int[size];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int mask = 0; mask < size; mask++) {
            if (dp[mask] == INF) continue;
            int available = 0;
            for (int i = 0; i < n; i++)
                if ((mask & (1 << i)) == 0 && (req[i] & mask) == req[i])
                    available |= 1 << i;

            if (Integer.bitCount(available) <= k) {
                int next = mask | available;
                dp[next] = Math.min(dp[next], dp[mask] + 1);
            } else {
                for (int sub = available; sub != 0; sub = (sub - 1) & available) {
                    if (Integer.bitCount(sub) <= k) {
                        int next = mask | sub;
                        dp[next] = Math.min(dp[next], dp[mask] + 1);
                    }
                }
            }
        }
        return dp[size - 1];
    }
}

